import React from 'react';
import { useState } from 'react';
import { motion } from 'framer-motion';

const figures = [
  {
    name: '안중근',
    image: process.env.PUBLIC_URL + '/images/ahn_faded.png',
    clearImage: process.env.PUBLIC_URL + '/images/ahn_clear.png',
    conversation: [
      '나는 조국의 독립을 위해 이토 히로부미를 처단했네.',
      '그날의 총성은 대한독립 만세를 외친 울림이었지.',
      '기억해줘. 진정한 평화는 정의 위에 세워져야 하네.'
    ]
  },
  {
    name: '유관순',
    image: process.env.PUBLIC_URL + '/images/yu_faded.png',
    clearImage: process.env.PUBLIC_URL +'/images/yu_clear.png',
    conversation: [
      '나는 3.1운동에 참여했어요. 그날, 우리는 모두 하나였죠.',
      '옥중에서도 자유를 외쳤어요. 끝까지 포기하지 않았죠.',
      '우리의 외침이 오늘의 대한민국을 만들었어요.'
    ]
  },
  {
    name: '김구',
    image: process.env.PUBLIC_URL + '/images/kim_faded.png',
    clearImage: process.env.PUBLIC_URL + '/images/kim_clear.png',
    conversation: [
      '나는 통일된 나라를 꿈꾸었네.',
      '내 소원은 오직 한 가지, 대한의 완전한 자주독립이었지.',
      '자유와 평화를 잊지 말아주게.'
    ]
  }
];

export default function MemorialGallery() {
  const [activeFigure, setActiveFigure] = useState(null);
  const [step, setStep] = useState(0);

  const handleClick = (figure) => {
    setActiveFigure(figure);
    setStep(0);
  };

  const nextStep = () => {
    if (step < activeFigure.conversation.length - 1) {
      setStep(step + 1);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <h1 className="text-3xl font-bold mb-8 text-center">디지털 추모관</h1>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {figures.map((figure) => (
          <motion.div
            key={figure.name}
            whileHover={{ scale: 1.05 }}
            onClick={() => handleClick(figure)}
            className="cursor-pointer text-center"
          >
            <img src={figure.image} alt={figure.name} className="mx-auto rounded-xl shadow-md" />
            <p className="mt-2 text-lg font-semibold">{figure.name}</p>
          </motion.div>
        ))}
      </div>

      {activeFigure && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl shadow-xl w-full max-w-lg text-center relative">
            <img
              src={step === activeFigure.conversation.length - 1 ? activeFigure.clearImage : activeFigure.image}
              alt={activeFigure.name}
              className="mx-auto rounded-xl mb-4 transition duration-500"
            />
            <p className="text-xl italic">"{activeFigure.conversation[step]}"</p>
            <div className="mt-4 flex justify-between">
              <button
                className="bg-gray-300 hover:bg-gray-400 text-gray-800 py-2 px-4 rounded"
                onClick={() => setActiveFigure(null)}
              >
                닫기
              </button>
              {step < activeFigure.conversation.length - 1 && (
                <button
                  className="bg-blue-500 hover:bg-blue-600 text-white py-2 px-4 rounded"
                  onClick={nextStep}
                >
                  다음
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
